{
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "title": "Substantive revision pair v1.3 — English",
  "type": "object",
  "additionalProperties": false,
  "required": [
    "pair_id",
    "pair_label",
    "version_metadata",
    "changes",
    "coverage",
    "inventory_complete",
    "unresolved_reasons",
    "summary"
  ],
  "properties": {
    "pair_id": {
      "type": "string",
      "minLength": 1,
      "description": "Return the input pair identifier unchanged; do not translate it."
    },
    "pair_label": {
      "enum": [
        "S2_SUBSTANTIVE",
        "S1_LIMITED",
        "S0_PRESENTATION",
        "U_UNRESOLVED"
      ],
      "description": "Exactly one label: S2 for a directly supported substantive research change; S1 for a confirmed limited addition or clarification; S0 for presentation-only or informationally equivalent changes after sufficient inspection; U for unresolved evidence. These are change labels, not scientific-quality scores."
    },
    "changes": {
      "type": "array",
      "items": {
        "$ref": "#/$defs/change"
      },
      "description": "Verified changes in order of importance. One reliable substantive change suffices for S2; do not pad the list. Newly authored explanatory text must be English."
    },
    "coverage": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "A",
        "B"
      ],
      "properties": {
        "A": {
          "$ref": "#/$defs/coverage"
        },
        "B": {
          "$ref": "#/$defs/coverage"
        }
      },
      "description": "Actual inspection coverage for the two supplied endpoints only. Input availability does not establish that material was inspected."
    },
    "inventory_complete": {
      "type": "boolean",
      "description": "Whether the inventory of changes is complete. S2 may be established with an incomplete inventory if at least one substantive change is reliable. S0 and S1 require complete relevant scientific coverage."
    },
    "unresolved_reasons": {
      "type": "array",
      "items": {
        "type": "string",
        "minLength": 1,
        "description": "An English account of an unresolved issue and the evidence needed to resolve it."
      },
      "description": "Specific unresolved evidentiary or interpretive issues in English, including how additional evidence could resolve them. Required to be nonempty for U; do not equate U with a negative finding."
    },
    "summary": {
      "type": "string",
      "minLength": 1,
      "description": "An English summary of the observed changes and the basis for the pair label, without quality scores, improvement requirements, or claims about other version pairs."
    },
    "version_metadata": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "A",
        "B"
      ],
      "properties": {
        "A": {
          "$ref": "#/$defs/version_metadata"
        },
        "B": {
          "$ref": "#/$defs/version_metadata"
        }
      },
      "description": "Supplied metadata for the two isolated pair endpoints only. Copy the original version IDs, verified physical PDF totals or unresolved statuses, and known source hashes; these values do not establish scientific inspection coverage."
    }
  },
  "$defs": {
    "anchor": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "pdf_pages",
        "location",
        "reported_content",
        "original_visual_checked"
      ],
      "properties": {
        "pdf_pages": {
          "type": "array",
          "items": {
            "type": "integer",
            "minimum": 1
          },
          "uniqueItems": true,
          "description": "Physical PDF page numbers counted from 1. An empty list is permitted when no corresponding location exists, with an explicit location statement and an actual absence or relocation check; never invent a page."
        },
        "location": {
          "type": "string",
          "minLength": 1,
          "description": "Source location in English, including section and table, figure, equation, or algorithm identifiers as applicable. If absent, state \"No corresponding location.\" Preserve original section titles or identifiers when necessary."
        },
        "reported_content": {
          "type": "string",
          "minLength": 1,
          "description": "An accurate English paraphrase of what this version reports. Necessary short source excerpts may remain verbatim. Do not infer when an experiment was performed or invent absent content."
        },
        "original_visual_checked": {
          "type": "boolean",
          "description": "Whether the original source page was actually inspected visually. Text extraction alone does not count as a visual check."
        }
      },
      "description": "A traceable source anchor in one supplied version. Write explanations in English; preserve original names, notation, identifiers, and necessary short source excerpts."
    },
    "change": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "category",
        "scope",
        "operation",
        "before",
        "after",
        "observed_difference",
        "qualifies_as_substantive",
        "rationale",
        "absence_or_relocation_check"
      ],
      "properties": {
        "category": {
          "enum": [
            "method_or_protocol",
            "data_or_task",
            "empirical_evidence",
            "theory_or_proof",
            "analysis_or_argument",
            "claim_or_limitation",
            "reproducibility",
            "presentation_or_metadata"
          ],
          "description": "The type of reported information affected. Related-work and introductory content are assessed by their actual scientific meaning, not excluded by section name."
        },
        "scope": {
          "enum": [
            "local",
            "multiple_sections",
            "core_reformulation"
          ],
          "description": "Extent of the change, recorded separately from its label. A local change can be substantive; a broad rewrite can be informationally equivalent."
        },
        "operation": {
          "enum": [
            "added",
            "removed",
            "revised",
            "relocated_or_equivalent",
            "reverted"
          ],
          "description": "The observed operation. Use reverted only when A and B themselves establish a reversion; otherwise use revised. Do not consult a third version."
        },
        "before": {
          "$ref": "#/$defs/anchor",
          "description": "Evidence from the earlier supplied version A."
        },
        "after": {
          "$ref": "#/$defs/anchor",
          "description": "Evidence from the later supplied version B."
        },
        "observed_difference": {
          "type": "string",
          "minLength": 1,
          "description": "An English description of the specific observed difference. Distinguish new reporting from speculation about author actions."
        },
        "qualifies_as_substantive": {
          "type": "boolean",
          "description": "Whether this change reliably meets at least one S2 criterion. Scientific improvement is not required. A reliable true item establishes S2 even if other regions remain uninspected."
        },
        "rationale": {
          "type": "string",
          "minLength": 1,
          "description": "Explain in English why the scientific information does or does not meet S2. Identify the actual method, evidence, argument, claim, or reproducibility change; edit size alone is not a reason."
        },
        "absence_or_relocation_check": {
          "type": [
            "string",
            "null"
          ],
          "description": "In English, document the actual search scope and findings used to establish absence or distinguish relocation or equivalent restatement. Required for added, removed, and relocated_or_equivalent; for equivalent restatement, explain that no addition or removal is asserted. Use null when not applicable. A diff alone does not establish absence."
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "operation": {
                "enum": [
                  "added",
                  "removed",
                  "relocated_or_equivalent"
                ]
              }
            }
          },
          "then": {
            "properties": {
              "absence_or_relocation_check": {
                "type": "string",
                "minLength": 1
              }
            }
          }
        }
      ],
      "description": "One verified change with directly supported before-and-after evidence and an English rationale. Classify the scientific information, not the edit length or direction of quality change."
    },
    "coverage": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "text_pdf_page_ranges_read",
        "visual_pdf_pages_checked",
        "scientific_content_complete",
        "gaps",
        "inspection_notes"
      ],
      "properties": {
        "text_pdf_page_ranges_read": {
          "type": "array",
          "items": {
            "type": "array",
            "prefixItems": [
              {
                "type": "integer",
                "minimum": 1
              },
              {
                "type": "integer",
                "minimum": 1
              }
            ],
            "minItems": 2,
            "maxItems": 2
          },
          "description": "Inclusive physical PDF page ranges actually read, each represented as [start, end], with pages counted from 1."
        },
        "visual_pdf_pages_checked": {
          "type": "array",
          "items": {
            "type": "integer",
            "minimum": 1
          },
          "uniqueItems": true,
          "description": "Physical PDF pages actually inspected visually, counted from 1. Required visual evidence cannot be replaced by extracted text."
        },
        "scientific_content_complete": {
          "type": "boolean",
          "description": "Whether all relevant scientific content for this endpoint has been inspected. S0 and S1 require this to be true; potentially consequential uninspected content makes an exclusion judgment unresolved."
        },
        "gaps": {
          "type": "array",
          "items": {
            "type": "string",
            "description": "An English description of one actual inspection gap."
          },
          "description": "English descriptions of missing, unreliable, or uninspected regions. Disclose coverage gaps even when a reliable S2 change has been established elsewhere."
        },
        "inspection_notes": {
          "type": "string",
          "description": "English notes on the inspection method, cross-section or appendix relocation searches, visual checks, and limitations. For long raw logs, describe any complete-diff navigation accurately; do not claim token-by-token reading unless it occurred."
        }
      },
      "description": "Truthful inspection coverage for one endpoint, including relevant scientific appendices and necessary original-page visual checks. Write notes and gaps in English."
    },
    "version_metadata": {
      "type": "object",
      "additionalProperties": false,
      "required": [
        "version",
        "page_count",
        "page_count_status",
        "page_count_reason",
        "pdf_sha256"
      ],
      "properties": {
        "version": {
          "type": "integer",
          "minimum": 1,
          "description": "Original positive version number of this endpoint; do not renumber selected versions."
        },
        "page_count": {
          "type": [
            "integer",
            "null"
          ],
          "minimum": 1,
          "description": "Exact total physical pages of this source PDF, including references and appendices in the same file; null if unresolved. Copy the supplied count, never infer it from printed numbering or text. Does not assert pages read."
        },
        "page_count_status": {
          "enum": [
            "verified",
            "unresolved"
          ]
        },
        "page_count_reason": {
          "type": [
            "string",
            "null"
          ],
          "minLength": 1,
          "description": "Specific English explanation when page count is unresolved; null when verified."
        },
        "pdf_sha256": {
          "type": [
            "string",
            "null"
          ],
          "pattern": "^[a-fA-F0-9]{64}$",
          "description": "SHA-256 of the exact supplied source PDF bytes, copied from verified provenance. Required for a verified count; may be known even when counting failed, or null if unavailable."
        }
      },
      "allOf": [
        {
          "if": {
            "properties": {
              "page_count_status": {
                "const": "verified"
              }
            },
            "required": [
              "page_count_status"
            ]
          },
          "then": {
            "properties": {
              "page_count": {
                "type": "integer",
                "minimum": 1
              },
              "page_count_reason": {
                "type": "null"
              },
              "pdf_sha256": {
                "type": "string",
                "pattern": "^[a-fA-F0-9]{64}$"
              }
            }
          }
        },
        {
          "if": {
            "properties": {
              "page_count_status": {
                "const": "unresolved"
              }
            },
            "required": [
              "page_count_status"
            ]
          },
          "then": {
            "properties": {
              "page_count": {
                "type": "null"
              },
              "page_count_reason": {
                "type": "string",
                "minLength": 1
              }
            }
          }
        }
      ]
    }
  },
  "allOf": [
    {
      "if": {
        "properties": {
          "pair_label": {
            "const": "S2_SUBSTANTIVE"
          }
        }
      },
      "then": {
        "properties": {
          "changes": {
            "minItems": 1,
            "contains": {
              "properties": {
                "qualifies_as_substantive": {
                  "const": true
                }
              },
              "required": [
                "qualifies_as_substantive"
              ]
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "pair_label": {
            "enum": [
              "S0_PRESENTATION",
              "S1_LIMITED"
            ]
          }
        }
      },
      "then": {
        "properties": {
          "coverage": {
            "properties": {
              "A": {
                "properties": {
                  "scientific_content_complete": {
                    "const": true
                  },
                  "gaps": {
                    "maxItems": 0
                  }
                }
              },
              "B": {
                "properties": {
                  "scientific_content_complete": {
                    "const": true
                  },
                  "gaps": {
                    "maxItems": 0
                  }
                }
              }
            }
          },
          "inventory_complete": {
            "const": true
          },
          "unresolved_reasons": {
            "maxItems": 0
          },
          "changes": {
            "items": {
              "properties": {
                "qualifies_as_substantive": {
                  "const": false
                }
              }
            }
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "pair_label": {
            "const": "U_UNRESOLVED"
          }
        }
      },
      "then": {
        "properties": {
          "unresolved_reasons": {
            "minItems": 1
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "pair_label": {
            "const": "S1_LIMITED"
          }
        }
      },
      "then": {
        "properties": {
          "changes": {
            "minItems": 1
          }
        }
      }
    },
    {
      "if": {
        "properties": {
          "pair_label": {
            "const": "U_UNRESOLVED"
          }
        }
      },
      "then": {
        "properties": {
          "changes": {
            "items": {
              "properties": {
                "qualifies_as_substantive": {
                  "const": false
                }
              }
            }
          }
        }
      }
    }
  ],
  "description": "English v1.3 output schema. Substantive labels and evidence thresholds are preserved, with required source-bound page-count metadata for A and B. A verified physical PDF count includes references and appendices in the same file and does not imply full inspection. The paper-level all-version ledger and strict selected-gap >30-day temporal gate are maintained outside this isolated pair judgment. This schema is prepared for future use and was not used for the existing 24 historical judgments. All newly authored explanations must be English; preserve identifiers, names, notation, and necessary short source quotations. Historical records and translations remain distinct from new executions."
}
